1	import React from 'react';
2	import { describe, test, expect, vi, beforeEach } from 'vitest';
3	import { render, screen } from '@testing-library/react';
4	import userEvent from '@testing-library/user-event';
5	import { ZimmWishlistAuthDrawer } from './index';
6	import { useWishlistAuthDrawer } from 'app/hooks/useWishlistAuthDrawer';
7	import type { UseWishlistAuthDrawerReturn } from 'app/hooks/useWishlistAuthDrawer';
8	
9	// ZimmDrawer's recipe (zimmDrawer.css.ts) has its own test coverage as of SFCC-831
10	// (zimmDrawer.css.test.ts); the component itself (index.tsx) has no index.test.tsx yet. Mock it
11	// to a minimal dialog stub regardless, so this suite can assert on open/close state without a
12	// full Chakra portal environment.
13	vi.mock('app/components/ui-kits/atoms/zimmDrawer', () => ({
14	  ZimmDrawer: ({
15	    isOpen,
16	    onClose,
17	    children,
18	  }: {
19	    isOpen: boolean;
20	    onClose: () => void;
21	    children: React.ReactNode;
22	  }) =>
23	    isOpen ? (
24	      <div role="dialog">
25	        <button onClick={onClose}>Close</button>
26	        {children}
27	      </div>
28	    ) : null,
29	}));
30	
31	// ZimmAuthDrawerContent's contract is covered by its own test file.
32	vi.mock('app/components/ui-kits/organisms/zimmAuthDrawerContent', () => ({
33	  ZimmAuthDrawerContent: () => <div data-testid="auth-drawer-content" />,
34	}));
35	
36	// OtpAuth and AuthModal are SFCC base components — stub shapes only.
37	vi.mock('@salesforce/retail-react-app/app/components/otp-auth', () => ({
38	  default: ({ isOpen }: { isOpen: boolean }) =>
39	    isOpen ? <div data-testid="otp-auth" /> : null,
40	}));
41	vi.mock('@salesforce/retail-react-app/app/hooks/use-auth-modal', () => ({
42	  AuthModal: () => null,
43	}));
44	
45	// All auth logic is in the hook — mock it to control state per test.
46	// A factory is required; without one, Vitest auto-imports the real module which pulls in
47	// SFCC's JSX contexts barrel and breaks the transform.
48	vi.mock('app/hooks/useWishlistAuthDrawer', () => ({
49	  useWishlistAuthDrawer: vi.fn(),
50	}));
51	
52	const mockUseWishlistAuthDrawer = vi.mocked(useWishlistAuthDrawer);
53	
54	function makeDefaultReturn(overrides: Partial<UseWishlistAuthDrawerReturn> = {}): UseWishlistAuthDrawerReturn {
55	  return {
56	    isOpen: false,
57	    handleDrawerClose: vi.fn(),
58	    handleTriggerClick: vi.fn(),
59	    triggerRef: { current: null },
60	    drawerTitle: 'Wishlist',
61	    description: 'You must log in or create an account to add items to your wishlist.',
62	    emailValue: '',
63	    onEmailChange: vi.fn(),
64	    onSendCode: vi.fn(),
65	    onSignInWithApple: undefined,
66	    onSignInWithGoogle: undefined,
67	    isSocialEnabled: false,
68	    isPasswordlessEnabled: true,
69	    emailInputRef: { current: null },
70	    socialError: undefined,
71	    onCreateAccount: vi.fn(),
72	    isOtpAuthOpen: false,
73	    onOtpAuthClose: vi.fn(),
74	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
75	    form: {} as any,
76	    handlePasswordlessLogin: vi.fn().mockResolvedValue({ success: true }),
77	    handleOtpVerification: vi.fn().mockResolvedValue({ success: true }),
78	    registerModal: { isOpen: false, onOpen: vi.fn(), onClose: vi.fn() } as UseWishlistAuthDrawerReturn['registerModal'],
79	    ...overrides,
80	  };
81	}
82	
83	describe('ZimmWishlistAuthDrawer', () => {
84	  beforeEach(() => {
85	    vi.clearAllMocks();
86	    mockUseWishlistAuthDrawer.mockReturnValue(makeDefaultReturn());
87	  });
88	
89	  describe('trigger wiring', () => {
90	    test('renders the child trigger element', () => {
91	      render(
92	        <ZimmWishlistAuthDrawer intentId="test-wishlist">
93	          <button>Wishlist</button>
94	        </ZimmWishlistAuthDrawer>,
95	      );
96	
97	      expect(screen.getByRole('button', { name: 'Wishlist' })).toBeInTheDocument();
98	    });
99	
100	    test('clicking the trigger calls handleTriggerClick', async () => {
101	      const handleTriggerClick = vi.fn();
102	      mockUseWishlistAuthDrawer.mockReturnValue(makeDefaultReturn({ handleTriggerClick }));
103	
104	      render(
105	        <ZimmWishlistAuthDrawer intentId="test-wishlist">
106	          <button>Add to wishlist</button>
107	        </ZimmWishlistAuthDrawer>,
108	      );
109	
110	      await userEvent.click(screen.getByRole('button', { name: 'Add to wishlist' }));
111	
112	      expect(handleTriggerClick).toHaveBeenCalledTimes(1);
113	    });
114	
115	    test('forwards intentId and onAuthSuccess to useWishlistAuthDrawer', () => {
116	      const onAuthSuccess = vi.fn();
117	      render(
118	        <ZimmWishlistAuthDrawer intentId="pdp-wishlist" onAuthSuccess={onAuthSuccess}>
119	          <button>Wishlist</button>
