    // Groups description + email form together with a tighter 32px gap (Figma: "Content").
    content: {
      display: 'flex',
      flexDirection: 'column',
      gap: 'var(--zimm-scale-2xl)',
      width: '100%',
    },

    description: {
      textStyle: 'body2',
